"""Write docs/cli.md from the forge parser."""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

from voxprint_forge.cli import build_parser


def render() -> str:
    """Markdown CLI reference generated from ``build_parser``."""
    lines = [
        "# CLI reference",
        "",
        "Generated from `forge` (`voxprint_forge.cli.build_parser`).",
        "Do not edit this file by hand. Run `python -m voxprint_forge.cli_reference`.",
        "",
    ]
    lines.extend(_section(build_parser(), "forge"))
    return "\n".join(lines).rstrip() + "\n"


def _section(parser: argparse.ArgumentParser, title: str) -> list[str]:
    blocks = [f"## `{title}`", "", "```text", parser.format_help().rstrip(), "```", ""]
    for action in parser._actions:
        if isinstance(action, argparse._SubParsersAction):
            for name, sub in action.choices.items():
                blocks.extend(_section(sub, f"{title} {name}"))
    return blocks


def main(argv: list[str] | None = None) -> int:
    """Write docs/cli.md, or exit 1 when ``--check`` finds it stale."""
    args = list(sys.argv[1:] if argv is None else argv)
    text = render()
    path = Path("docs/cli.md")
    if "--check" in args:
        current = path.read_text(encoding="utf-8") if path.is_file() else ""
        if current != text:
            print("docs/cli.md does not match the forge parser", file=sys.stderr)
            return 1
        return 0
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main())
